CREATE TABLE "competition_event_result_sheet" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "event_id" bigint UNIQUE NOT NULL,
    "mode" varchar(16) NOT NULL,
    "task_count" smallint NOT NULL,
    "status" varchar(16) NOT NULL DEFAULT 'draft',
    "calculated_at" timestamptz,
    "approved_by_user_id" bigint,
    "approved_at" timestamptz,
    "protocol_storage_key" text,
    "created_at" timestamptz NOT NULL DEFAULT now(),
    "updated_at" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "competition_event_result_sheet_event_id_fkey"
        FOREIGN KEY ("event_id") REFERENCES "competition_event" ("id") ON DELETE CASCADE,
    CONSTRAINT "competition_event_result_sheet_approved_by_fkey"
        FOREIGN KEY ("approved_by_user_id") REFERENCES "user" ("id"),
    CONSTRAINT "competition_event_result_sheet_mode_check"
        CHECK ("mode" IN ('individual', 'team')),
    CONSTRAINT "competition_event_result_sheet_task_count_check"
        CHECK ("task_count" BETWEEN 1 AND 50),
    CONSTRAINT "competition_event_result_sheet_status_check"
        CHECK ("status" IN ('draft', 'approved'))
);

CREATE TABLE "competition_event_result_entry" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "sheet_id" bigint NOT NULL,
    "team_id" bigint,
    "result_status" varchar(30) NOT NULL DEFAULT 'finished',
    "solved_count" integer NOT NULL DEFAULT 0,
    "total_time_deciseconds" bigint NOT NULL DEFAULT 0,
    "last_solve_time_deciseconds" bigint NOT NULL DEFAULT 0,
    "negative_attempts" integer NOT NULL DEFAULT 0,
    "place" integer,
    CONSTRAINT "competition_event_result_entry_sheet_id_fkey"
        FOREIGN KEY ("sheet_id") REFERENCES "competition_event_result_sheet" ("id") ON DELETE CASCADE,
    CONSTRAINT "competition_event_result_entry_team_id_fkey"
        FOREIGN KEY ("team_id") REFERENCES "team" ("id"),
    CONSTRAINT "competition_event_result_entry_status_check"
        CHECK ("result_status" IN ('finished', 'did_not_start', 'disqualified')),
    CONSTRAINT "competition_event_result_entry_summary_check"
        CHECK (
            "solved_count" >= 0
            AND "total_time_deciseconds" >= 0
            AND "last_solve_time_deciseconds" >= 0
            AND "negative_attempts" >= 0
            AND ("place" IS NULL OR "place" > 0)
        )
);

CREATE UNIQUE INDEX "competition_event_result_entry_team_idx"
    ON "competition_event_result_entry" ("sheet_id", "team_id")
    WHERE "team_id" IS NOT NULL;

CREATE TABLE "competition_event_result_entry_application" (
    "entry_id" bigint NOT NULL,
    "application_id" bigint UNIQUE NOT NULL,
    PRIMARY KEY ("entry_id", "application_id"),
    CONSTRAINT "competition_event_result_entry_application_entry_fkey"
        FOREIGN KEY ("entry_id") REFERENCES "competition_event_result_entry" ("id") ON DELETE CASCADE,
    CONSTRAINT "competition_event_result_entry_application_application_fkey"
        FOREIGN KEY ("application_id") REFERENCES "competition_application" ("id") ON DELETE RESTRICT
);

CREATE TABLE "competition_event_task_result" (
    "entry_id" bigint NOT NULL,
    "task_number" smallint NOT NULL,
    "status" varchar(20) NOT NULL,
    "solve_time_deciseconds" bigint,
    "negative_attempts" integer NOT NULL DEFAULT 0,
    PRIMARY KEY ("entry_id", "task_number"),
    CONSTRAINT "competition_event_task_result_entry_fkey"
        FOREIGN KEY ("entry_id") REFERENCES "competition_event_result_entry" ("id") ON DELETE CASCADE,
    CONSTRAINT "competition_event_task_result_number_check"
        CHECK ("task_number" BETWEEN 1 AND 50),
    CONSTRAINT "competition_event_task_result_status_check"
        CHECK ("status" IN ('not_attempted', 'attempted', 'solved')),
    CONSTRAINT "competition_event_task_result_values_check"
        CHECK (
            "negative_attempts" >= 0
            AND (
                ("status" = 'solved' AND "solve_time_deciseconds" IS NOT NULL AND "solve_time_deciseconds" >= 0)
                OR ("status" <> 'solved' AND "solve_time_deciseconds" IS NULL)
            )
        )
);

CREATE INDEX "competition_event_result_entry_sheet_idx"
    ON "competition_event_result_entry" ("sheet_id", "id");

COMMENT ON TABLE "competition_event_result_sheet" IS
    'Черновик или утверждённый зачёт конкретного мероприятия соревнования';
COMMENT ON COLUMN "competition_event_task_result"."solve_time_deciseconds" IS
    'Время положительного решения задачи в десятых долях секунды';
COMMENT ON COLUMN "competition_event_task_result"."negative_attempts" IS
    'Количество отрицательных решений по задаче до положительного решения или окончания зачёта';
